PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS jurisdictions(id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bodies(id TEXT PRIMARY KEY, jurisdiction_id TEXT NOT NULL REFERENCES jurisdictions(id), name TEXT NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY, name TEXT NOT NULL, official_url TEXT, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS body_versions(id TEXT PRIMARY KEY, body_id TEXT NOT NULL REFERENCES bodies(id), effective_from TEXT NOT NULL, effective_to TEXT, source_version_id TEXT, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY, body_id TEXT NOT NULL REFERENCES bodies(id), person_id TEXT NOT NULL REFERENCES people(id), effective_from TEXT NOT NULL, effective_to TEXT, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS procedure_versions(id TEXT PRIMARY KEY, body_id TEXT NOT NULL REFERENCES bodies(id), effective_from TEXT NOT NULL, effective_to TEXT, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY, body_id TEXT REFERENCES bodies(id), source_url TEXT NOT NULL, starts_at TEXT, kind TEXT NOT NULL, coverage_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meeting_identifiers(namespace TEXT NOT NULL, value TEXT NOT NULL, meeting_id TEXT NOT NULL REFERENCES meetings(id), PRIMARY KEY(namespace,value));
CREATE TABLE IF NOT EXISTS matters(id TEXT PRIMARY KEY, jurisdiction_id TEXT NOT NULL REFERENCES jurisdictions(id), title TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS matter_identifiers(jurisdiction_id TEXT NOT NULL REFERENCES jurisdictions(id), namespace TEXT NOT NULL, value TEXT NOT NULL, matter_id TEXT NOT NULL REFERENCES matters(id), PRIMARY KEY(jurisdiction_id,namespace,value));
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY, name TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topic_matters(topic_id TEXT REFERENCES topics(id), matter_id TEXT REFERENCES matters(id), PRIMARY KEY(topic_id,matter_id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, matter_id TEXT REFERENCES matters(id), source_url TEXT NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appearances(id TEXT PRIMARY KEY, meeting_id TEXT NOT NULL REFERENCES meetings(id), matter_id TEXT REFERENCES matters(id), agenda_number TEXT, official_disposition TEXT NOT NULL, action_type TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS motions(id TEXT PRIMARY KEY, appearance_id TEXT NOT NULL REFERENCES appearances(id), kind TEXT NOT NULL, official_text TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS amendments(id TEXT PRIMARY KEY, motion_id TEXT NOT NULL REFERENCES motions(id), matter_id TEXT REFERENCES matters(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vote_events(id TEXT PRIMARY KEY, meeting_id TEXT REFERENCES meetings(id), appearance_id TEXT REFERENCES appearances(id), motion_id TEXT REFERENCES motions(id), event_kind TEXT NOT NULL, origin TEXT NOT NULL, review_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vote_event_matters(vote_event_id TEXT REFERENCES vote_events(id), matter_id TEXT REFERENCES matters(id), included INTEGER NOT NULL, removal_evidence TEXT, PRIMARY KEY(vote_event_id,matter_id));
CREATE TABLE IF NOT EXISTS individual_votes(id TEXT PRIMARY KEY, vote_event_id TEXT NOT NULL REFERENCES vote_events(id), person_id TEXT REFERENCES people(id), position TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vote_crosschecks(id TEXT PRIMARY KEY, agenda_event_id TEXT REFERENCES vote_events(id), register_event_id TEXT REFERENCES vote_events(id), status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_versions(id TEXT PRIMARY KEY, url TEXT NOT NULL, retrieved_at TEXT NOT NULL, content_hash TEXT NOT NULL, parser_version TEXT NOT NULL, meaningful_hash TEXT NOT NULL, artifact_path TEXT NOT NULL, UNIQUE(url,content_hash,parser_version));
CREATE TABLE IF NOT EXISTS source_current(url TEXT PRIMARY KEY, version_id TEXT REFERENCES source_versions(id), meaningful_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retrievals(id INTEGER PRIMARY KEY, pipeline TEXT NOT NULL, url TEXT NOT NULL, at TEXT NOT NULL, status TEXT NOT NULL, version_id TEXT REFERENCES source_versions(id), error TEXT);
CREATE TABLE IF NOT EXISTS passages(id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES source_versions(id), locator TEXT NOT NULL, text TEXT NOT NULL, start_seconds REAL, end_seconds REAL, evidence_kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS facts(id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, predicate TEXT NOT NULL, value TEXT NOT NULL, passage_id TEXT NOT NULL REFERENCES passages(id), status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pipeline_runs(id TEXT PRIMARY KEY, pipeline TEXT NOT NULL, started_at TEXT NOT NULL, ingestion_status TEXT NOT NULL, parsing_status TEXT NOT NULL, reconciliation_status TEXT NOT NULL, generation_status TEXT NOT NULL, editorial_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_scans(id TEXT PRIMARY KEY, pipeline_run_id TEXT REFERENCES pipeline_runs(id), source_url TEXT NOT NULL, complete INTEGER NOT NULL, pages INTEGER NOT NULL, expected_count INTEGER, parsed_count INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS changes(id TEXT PRIMARY KEY, url TEXT NOT NULL, old_version TEXT, new_version TEXT, kind TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meeting_reports(id TEXT PRIMARY KEY, meeting_id TEXT NOT NULL REFERENCES meetings(id), phase TEXT NOT NULL, current_version TEXT, state TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(meeting_id,phase));
CREATE TABLE IF NOT EXISTS report_versions(id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES meeting_reports(id), created_at TEXT NOT NULL, evidence_bundle TEXT NOT NULL, claims TEXT NOT NULL, article TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_audit(id INTEGER PRIMARY KEY, report_id TEXT REFERENCES meeting_reports(id), version_id TEXT REFERENCES report_versions(id), action TEXT NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL, review_seconds REAL NOT NULL, note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS boundary_datasets(id TEXT PRIMARY KEY, kind TEXT NOT NULL, source_url TEXT NOT NULL, version_id TEXT REFERENCES source_versions(id), crs TEXT NOT NULL, complete INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS filing_events(id TEXT PRIMARY KEY, jurisdiction_id TEXT REFERENCES jurisdictions(id), case_identifier TEXT NOT NULL, stage TEXT NOT NULL, source_url TEXT NOT NULL, version_id TEXT REFERENCES source_versions(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS location_tags(id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, area_kind TEXT NOT NULL, area_id TEXT, relation TEXT NOT NULL, method TEXT NOT NULL, evidence TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS association_sources(id TEXT PRIMARY KEY, name TEXT NOT NULL, neighborhood_id TEXT, url TEXT NOT NULL, material_kind TEXT NOT NULL, last_success_at TEXT, status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS capture_jobs(id TEXT PRIMARY KEY, meeting_id TEXT NOT NULL REFERENCES meetings(id), source_url TEXT NOT NULL, mode TEXT NOT NULL, state TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS capture_segments(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES capture_jobs(id), start_seconds REAL NOT NULL, end_seconds REAL NOT NULL, artifact_path TEXT NOT NULL, content_hash TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS capture_gaps(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES capture_jobs(id), start_seconds REAL NOT NULL, end_seconds REAL, reason TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transcript_segments(id TEXT PRIMARY KEY, job_id TEXT REFERENCES capture_jobs(id), meeting_id TEXT NOT NULL REFERENCES meetings(id), start_seconds REAL NOT NULL, end_seconds REAL NOT NULL, raw_text TEXT NOT NULL, raw_speaker TEXT, corrected_text TEXT, person_id TEXT REFERENCES people(id), attribution_status TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scheduled_jobs(id TEXT PRIMARY KEY, pipeline TEXT NOT NULL, due_at TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS collection_checkpoints(pipeline TEXT PRIMARY KEY, completed_at TEXT, data TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS vote_event_versions(id TEXT PRIMARY KEY, vote_event_id TEXT NOT NULL REFERENCES vote_events(id), source_passage_id TEXT NOT NULL REFERENCES passages(id), data TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS register_observations(id TEXT PRIMARY KEY, matter_id TEXT REFERENCES matters(id), publication_date TEXT NOT NULL, person_id TEXT REFERENCES people(id), position TEXT NOT NULL, passage_id TEXT REFERENCES passages(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS person_aliases(alias TEXT PRIMARY KEY,person_id TEXT REFERENCES people(id),method TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_records(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, folder_id INTEGER NOT NULL, source_url TEXT NOT NULL, source_version TEXT NOT NULL REFERENCES source_versions(id), passage_id TEXT NOT NULL REFERENCES passages(id), content_hash TEXT NOT NULL, state TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(source_id,folder_id));
CREATE TABLE IF NOT EXISTS development_versions(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES development_records(id), source_version TEXT NOT NULL REFERENCES source_versions(id), passage_id TEXT NOT NULL REFERENCES passages(id), content_hash TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_reports(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES development_records(id), current_version TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_report_versions(id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES development_reports(id), created_at TEXT NOT NULL, record_hash TEXT NOT NULL, evidence_bundle TEXT NOT NULL, claims TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_review_audit(id INTEGER PRIMARY KEY, report_id TEXT NOT NULL, version_id TEXT NOT NULL, action TEXT NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL, review_seconds REAL NOT NULL, note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_relationships(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES development_records(id), related_identifier TEXT NOT NULL, kind TEXT NOT NULL, passage_id TEXT NOT NULL REFERENCES passages(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_evidence(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES development_records(id), source_url TEXT NOT NULL, source_version TEXT NOT NULL REFERENCES source_versions(id), passage_id TEXT NOT NULL REFERENCES passages(id), kind TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS government_watch_runs(id TEXT PRIMARY KEY, checked_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meeting_watch_entries(id TEXT PRIMARY KEY REFERENCES meetings(id), checked_at TEXT NOT NULL, source_version TEXT NOT NULL REFERENCES source_versions(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS election_watch_versions(id TEXT PRIMARY KEY REFERENCES source_versions(id), checked_at TEXT NOT NULL, data TEXT NOT NULL);
